sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmName ?director ?directorName ?deathDate WHERE {
  VALUES ?film { dbr:La_otra_imagen dbr:The_Gentle_Art_of_Burglary }

  # director (prefer dbp:director)
  OPTIONAL { ?film dbp:director ?dirDbp . }
  OPTIONAL { ?film dbo:director ?dirDbo . }
  BIND (COALESCE(?dirDbp, ?dirDbo) AS ?director)

  # director death date (prefer dbp:deathDate)
  OPTIONAL { ?director dbp:deathDate ?deathDateDbp . }
  OPTIONAL { ?director dbo:deathDate ?deathDateDbo . }
  BIND (COALESCE(?deathDateDbp, ?deathDateDbo) AS ?deathDate)

  # optional English labels for readability
  OPTIONAL { ?film rdfs:label ?filmName . FILTER (lang(?filmName) = "en") }
  OPTIONAL { ?director rdfs:label ?directorName . FILTER (lang(?directorName) = "en") }
}
LIMIT 100

